<?php
require_once __DIR__.'/../includes/functions.php';
$token=$_GET['token']??'';$st=db()->prepare('SELECT s.*,f.file_name,f.mime_type,f.file_size,f.s3_key FROM shares s JOIN files f ON f.id=s.file_id WHERE s.token=? AND s.revoked_at IS NULL AND (s.expires_at IS NULL OR s.expires_at>NOW()) LIMIT 1');$st->execute([$token]);$share=$st->fetch();
if(!$share){http_response_code(404);exit('Share link is invalid or expired.');}
$url=create_presigned_url($share['s3_key'],10);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Shared file — FluxDrive</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet"><link rel="stylesheet" href="assets/css/style.css"></head><body class="auth-page"><div class="auth-card text-center"><div class="brand justify-content-center mb-4"><span class="brand-mark"><i class="bi bi-cloud-arrow-up"></i></span>FluxDrive</div><div class="file-icon lg mx-auto mb-3"><i class="bi <?=e(icon_for($share['mime_type']))?>"></i></div><h2><?=e($share['file_name'])?></h2><p class="muted"><?=e(human_bytes((int)$share['file_size']))?></p><div class="d-flex gap-2 justify-content-center"><a class="btn btn-primary" href="<?=e($url)?>" target="_blank"><i class="bi bi-download"></i> Download</a><a class="btn btn-light border" href="<?=e($url)?>" target="_blank">Open</a></div></div></body></html>
